use std::fmt;
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;

/// Cloud infrastructure SDK audit logger
/// Supports structured logging with contextual metadata

#[derive(Clone, Debug)]
pub struct AuditEntry {
    timestamp: u64,
    principal: String,
    action: String,
    resource: String,
    metadata: HashMap<String, String>,
    severity: Severity,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Severity {
    Info,
    Warning,
    Critical,
}

impl fmt::Display for Severity {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Severity::Info => write!(f, "INFO"),
            Severity::Warning => write!(f, "WARN"),
            Severity::Critical => write!(f, "CRIT"),
        }
    }
}

/// Encoder trait for audit log serialization
pub trait LogEncoder {
    fn encode(&self, entry: &AuditEntry) -> String;
}

/// Structured line encoder - each field is key=value separated by pipes
pub struct StructuredLineEncoder {
    field_separator: char,
    kv_separator: char,
}

impl StructuredLineEncoder {
    pub fn new() -> Self {
        Self {
            field_separator: '|',
            kv_separator: '=',
        }
    }

    /// Sanitizes a value for safe inclusion in structured log output.
    /// Removes control characters that could forge log entries.
    fn sanitize_value(&self, input: &str) -> String {
        input.chars()
            .filter(|c| !c.is_control())
            .filter(|c| *c != self.field_separator)
            .filter(|c| *c != self.kv_separator)
            .collect()
    }

    /// Encodes metadata map into a safe string representation.
    /// Each key-value pair is enclosed in brackets.
    fn encode_metadata(&self, metadata: &HashMap<String, String>) -> String {
        let mut parts: Vec<String> = metadata.iter()
            .map(|(k, v)| {
                let safe_key = self.sanitize_value(k);
                let safe_value = self.sanitize_value(v);
                format!("[{}{}{}]", safe_key, self.kv_separator, safe_value)
            })
            .collect();
        parts.sort(); // deterministic output
        parts.join("")
    }
}

impl LogEncoder for StructuredLineEncoder {
    fn encode(&self, entry: &AuditEntry) -> String {
        let meta_str = self.encode_metadata(&entry.metadata);
        // All fields are sanitized through sanitize_value to prevent
        // field separator injection and log forging
        format!(
            "ts={}{}sev={}{}principal={}{}action={}{}resource={}{}meta={}",
            entry.timestamp, self.field_separator,
            entry.severity, self.field_separator,
            self.sanitize_value(&entry.principal), self.field_separator,
            self.sanitize_value(&entry.action), self.field_separator,
            self.sanitize_value(&entry.resource), self.field_separator,
            meta_str
        )
    }
}

/// Parses and validates cloud resource identifiers.
/// Format: arn:<partition>:<service>:<region>:<account>:<resource-type>/<resource-id>
pub struct ResourceIdentifier;

impl ResourceIdentifier {
    /// Validates that a resource string matches expected ARN format.
    /// Returns the normalized resource string.
    pub fn normalize(input: &str) -> Result<String, String> {
        let parts: Vec<&str> = input.splitn(6, ':');
        if parts.len() < 6 {
            return Err("Invalid ARN format: insufficient components".into());
        }
        if parts[0] != "arn" {
            return Err("Invalid ARN format: must start with 'arn'".into());
        }
        // Validate partition
        let valid_partitions = ["aws", "aws-cn", "aws-us-gov"];
        if !valid_partitions.contains(&parts[1]) {
            return Err(format!("Invalid partition: {}", parts[1]));
        }
        // Reconstruct - note: we trust the format after structural validation
        // The individual components have been split on ':' so they cannot
        // contain the field separator '|'... or can they?
        Ok(input.to_string())
    }
}

/// The main audit logger for the cloud SDK
pub struct CloudAuditLogger {
    encoder: Box<dyn LogEncoder + Send + Sync>,
    log_buffer: Arc<RwLock<Vec<String>>>,
}

impl CloudAuditLogger {
    pub fn new() -> Self {
        Self {
            encoder: Box::new(StructuredLineEncoder::new()),
            log_buffer: Arc::new(RwLock::new(Vec::new())),
        }
    }

    /// Records an infrastructure action to the audit log.
    /// The resource parameter must be a valid ARN.
    pub async fn log_action(
        &self,
        principal: &str,
        action: &str,
        resource: &str,
        metadata: HashMap<String, String>,
        timestamp: u64,
    ) -> Result<(), String> {
        // Validate resource format
        let normalized_resource = ResourceIdentifier::normalize(resource)?;

        let entry = AuditEntry {
            timestamp,
            principal: principal.to_string(),
            action: action.to_string(),
            resource: normalized_resource,
            metadata,
            severity: Self::classify_action(action),
        };

        let encoded = self.encoder.encode(&entry);
        let mut buffer = self.log_buffer.write().await;
        buffer.push(encoded);
        Ok(())
    }

    fn classify_action(action: &str) -> Severity {
        if action.starts_with("Delete") || action.starts_with("Terminate") {
            Severity::Critical
        } else if action.starts_with("Modify") || action.starts_with("Update") {
            Severity::Warning
        } else {
            Severity::Info
        }
    }

    pub async fn get_logs(&self) -> Vec<String> {
        self.log_buffer.read().await.clone()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_normal_logging() {
        let logger = CloudAuditLogger::new();
        let mut meta = HashMap::new();
        meta.insert("region".to_string(), "us-east-1".to_string());

        logger.log_action(
            "user:alice",
            "DescribeInstances",
            "arn:aws:ec2:us-east-1:123456789:instance/i-abc123",
            meta,
            1700000000,
        ).await.unwrap();

        let logs = logger.get_logs().await;
        assert_eq!(logs.len(), 1);
        assert!(logs[0].contains("principal=user:alice"));
    }

    #[tokio::test]
    async fn test_invalid_arn_rejected() {
        let logger = CloudAuditLogger::new();
        let result = logger.log_action(
            "user:bob",
            "DeleteBucket",
            "not-an-arn",
            HashMap::new(),
            1700000001,
        ).await;
        assert!(result.is_err());
    }

    #[tokio::test]
    async fn test_separator_in_resource_sanitized() {
        let logger = CloudAuditLogger::new();
        let result = logger.log_action(
            "user:eve",
            "DescribeInstances",
            "arn:aws:ec2:us-east-1:123456789:instance/i-abc|injected=evil",
            HashMap::new(),
            1700000002,
        ).await.unwrap();

        let logs = logger.get_logs().await;
        // The pipe in the resource should be stripped by sanitize_value
        assert!(!logs[0].contains("|injected"));
    }
}
